function sraSame(T,verse,means,ans,ol){const SW=new Set('this that these those which where there their about answe under above below again other being given every stand throu links round verse press place shown named first later after state means shall would could should never gives'.split(' '));const st=s=>new Set((String(s||'').toLowerCase().match(/[a-z]{5,}/g)||[]).map(w=>w.slice(0,5)).filter(w=>!SW.has(w)));const A=st(ans);const ks=[...st(means)].filter(k=>!A.has(k));if(!ks.length)return '';const re=new RegExp('(?<![A-Za-z0-9])'+String(verse).trim().replace(/[.*+?^${}()|[\]\\]/g,'\\$&').replace(/\s+/g,'\\s*')+'(?![0-9])','i');const NN=s=>String(s||'').toLowerCase().replace(/[^a-z0-9 ]+/g,' ').replace(/\s+/g,' ').trim();const awl=NN(ans).split(' ').filter(Boolean),AW=[];for(let i=0;i+6<=awl.length;i++)AW.push(awl.slice(i,i+6).join(' '));if(awl.length>=3&&awl.length<6)AW.push(awl.join(' '));const MW=NN(means);const O=NN(ol);const P=String(T||'').split('\n').map(p=>p.trim()).filter(p=>NN(p).split(' ').length>=6&&!re.test(p)&&!/PRESSED WITH|--\s*MEANS\s*:|^#{1,6}\s|^\**\s*LINK\s+\d|\bROUND\s+\d\b.*\bROUND\b|^(?:DEFENDER|CHALLENGER)\b.*--/i.test(p)&&!/^[\W_]*MEANS\b|^[\W_]*\d+[.)]\s/i.test(p)&&!(MW&&NN(p).includes(MW))&&!AW.some(w=>NN(p).includes(w))&&!(O&&O.includes(NN(p))));if(!P.length)return '';const S=P.map(st);const df={};for(const k of ks)df[k]=S.filter(s=>s.has(k)).length;const sc=P.map((p,i)=>({p,i,v:ks.reduce((t,k)=>t+(S[i].has(k)?1/df[k]:0),0)})).filter(x=>x.v>=0.5&&ks.some(k=>df[k]<=3&&S[x.i].has(k))).sort((x,y)=>y.v-x.v||x.i-y.i).slice(0,2);return sc.map(x=>x.p.length>400?x.p.slice(0,400)+' ...':x.p).join('\n');} /* pkgSRA rev 3: no MEANS, numbered, meaning-holding or answer-holding line. same-round lines that carry words of the stated meaning the answer does not use */
